int load_user(int id, struct user *out);

int render(int id, char *buf, size_t n) {
    struct user u;
    int rc = load_user(id, &u);    /* value + status, checked by hand */
    if (rc != 0) goto fail;
    rc = format_user(&u, buf, n);  /* only runs if the load succeeded */
fail:
    return rc;                     /* no bind: propagation is explicit */
}
